mapper.update:
UPDATE memory_extraction_task SET lease_until=#{deadline}
WHERE task_id=#{task.id} AND lease_owner=#{task.owner} AND status='RUNNING'
    AND lease_until >= CURRENT_TIMESTAMP

mapper.select:
SELECT task_id FROM memory_extraction_task
WHERE task_id=#{task.id} AND status='RUNNING' AND lease_owner=#{task.owner}
  AND lease_until >= CURRENT_TIMESTAMP FOR UPDATE
